# Standard Library Interfaces di Go

Go standard library mendefinisikan beberapa interface fundamental yang digunakan di seluruh ekosistem Go. Memahami dan mengimplementasikan interface ini membuat kode kamu terintegrasi dengan baik dengan ekosistem Go.

## io.Reader

```go
// Dari package io
type Reader interface {
    Read(p []byte) (n int, err error)
}
```

`io.Reader` adalah interface yang paling banyak digunakan di Go. Diimplementasikan oleh file, HTTP request body, string reader, dan lainnya:

```go
import (
    "fmt"
    "io"
    "strings"
)

// strings.NewReader mengimplementasikan io.Reader
r := strings.NewReader("Hello, Go!")
buf := make([]byte, 4)
for {
    n, err := r.Read(buf)
    if err == io.EOF {
        break
    }
    fmt.Printf("Read %d bytes: %s\n", n, buf[:n])
}

// Implementasi io.Reader kustom
type RepeatReader struct {
    data  []byte
    count int
    pos   int
}

func (r *RepeatReader) Read(p []byte) (int, error) {
    if r.count <= 0 {
        return 0, io.EOF
    }
    n := copy(p, r.data[r.pos:])
    r.pos += n
    if r.pos >= len(r.data) {
        r.pos = 0
        r.count--
    }
    return n, nil
}
```

## io.Writer

```go
type Writer interface {
    Write(p []byte) (n int, err error)
}
```

```go
import (
    "bytes"
    "fmt"
    "os"
)

// os.Stdout mengimplementasikan io.Writer
fmt.Fprintln(os.Stdout, "Hello, Writer!")

// bytes.Buffer mengimplementasikan io.Writer dan io.Reader
var buf bytes.Buffer
buf.WriteString("Hello")
fmt.Fprintf(&buf, ", %s!", "World")
fmt.Println(buf.String()) // Hello, World!

// Fungsi yang menerima io.Writer — sangat fleksibel
func writeReport(w io.Writer, title string, data []string) {
    fmt.Fprintf(w, "=== %s ===\n", title)
    for i, d := range data {
        fmt.Fprintf(w, "%d. %s\n", i+1, d)
    }
}

// Bisa tulis ke file, buffer, atau stdout!
writeReport(os.Stdout, "Laporan", []string{"Item 1", "Item 2"})

var out bytes.Buffer
writeReport(&out, "Laporan", []string{"Item 1", "Item 2"})
fmt.Println(out.String())
```

## fmt.Stringer

```go
// Dari package fmt
type Stringer interface {
    String() string
}
```

Implementasikan `Stringer` untuk representasi string kustom:

```go
type Point struct {
    X, Y int
}

func (p Point) String() string {
    return fmt.Sprintf("(%d, %d)", p.X, p.Y)
}

type Color struct {
    R, G, B uint8
}

func (c Color) String() string {
    return fmt.Sprintf("#%02X%02X%02X", c.R, c.G, c.B)
}

p := Point{3, 4}
fmt.Println(p)        // (3, 4) — menggunakan String() otomatis
fmt.Printf("%v\n", p) // (3, 4)
fmt.Printf("%s\n", p) // (3, 4)

red := Color{255, 0, 0}
fmt.Println(red) // #FF0000
```

## error Interface

```go
// Built-in error interface
type error interface {
    Error() string
}
```

```go
// Implementasi custom error
type AppError struct {
    Code    int
    Message string
    Err     error // wrapped error
}

func (e *AppError) Error() string {
    if e.Err != nil {
        return fmt.Sprintf("[%d] %s: %v", e.Code, e.Message, e.Err)
    }
    return fmt.Sprintf("[%d] %s", e.Code, e.Message)
}

func (e *AppError) Unwrap() error {
    return e.Err
}

func findUser(id int) error {
    if id <= 0 {
        return &AppError{Code: 400, Message: "invalid user ID"}
    }
    if id > 1000 {
        return &AppError{Code: 404, Message: "user not found"}
    }
    return nil
}

err := findUser(9999)
if err != nil {
    fmt.Println(err) // [404] user not found
}
```

## io.Closer

```go
type Closer interface {
    Close() error
}
```

Umumnya digunakan dengan `defer` untuk memastikan resource di-release:

```go
// File mengimplementasikan io.ReadWriteCloser
f, err := os.Open("data.txt")
if err != nil {
    log.Fatal(err)
}
defer f.Close() // selalu tutup!

// Fungsi yang mengelola resource apapun yang bisa ditutup
func readAndClose(rc io.ReadCloser) ([]byte, error) {
    defer rc.Close()
    return io.ReadAll(rc)
}
```

## Implementasi Stringer pada Tipe Kustom

```go
type Weekday int

const (
    Senin Weekday = iota + 1
    Selasa
    Rabu
    Kamis
    Jumat
    Sabtu
    Minggu
)

func (w Weekday) String() string {
    names := []string{"", "Senin", "Selasa", "Rabu",
        "Kamis", "Jumat", "Sabtu", "Minggu"}
    if int(w) < 1 || int(w) > 7 {
        return fmt.Sprintf("Weekday(%d)", int(w))
    }
    return names[w]
}

day := Rabu
fmt.Println(day)          // Rabu
fmt.Printf("Hari: %s\n", day) // Hari: Rabu
```

