# Standard Library Interfaces in Go

Go's standard library defines several fundamental interfaces used throughout the Go ecosystem. Understanding and implementing these interfaces makes your code integrate well with the Go world.

## io.Reader

```go
type Reader interface {
    Read(p []byte) (n int, err error)
}
```

Implemented by files, HTTP request bodies, string readers, and more:

```go
r := strings.NewReader("Hello, Go!")
buf := make([]byte, 4)
for {
    n, err := r.Read(buf)
    if err == io.EOF { break }
    fmt.Printf("Read %d bytes: %s\n", n, buf[:n])
}
```

## io.Writer

```go
// Accept io.Writer for maximum flexibility
func writeReport(w io.Writer, title string, items []string) {
    fmt.Fprintf(w, "=== %s ===\n", title)
    for i, item := range items {
        fmt.Fprintf(w, "%d. %s\n", i+1, item)
    }
}
// Write to stdout, file, or buffer!
```

## fmt.Stringer

```go
type Point struct{ X, Y int }
func (p Point) String() string {
    return fmt.Sprintf("(%d, %d)", p.X, p.Y)
}

p := Point{3, 4}
fmt.Println(p) // (3, 4) — String() called automatically
```

## error Interface

```go
type error interface { Error() string }

type AppError struct { Code int; Message string }
func (e *AppError) Error() string {
    return fmt.Sprintf("[%d] %s", e.Code, e.Message)
}
```

## io.Closer

```go
f, _ := os.Open("data.txt")
defer f.Close() // always close resources!
```

starterCode:
package main

import (
	"bytes"
	"fmt"
	"io"
	"strings"
)

// Custom type implementing fmt.Stringer
type Temperature struct {
	Celsius float64
}

func (t Temperature) String() string {
	return fmt.Sprintf("%.1f°C (%.1f°F)", t.Celsius, t.Celsius*9/5+32)
}

// Custom error type
type ParseError struct {
	Input string
	Msg   string
}

func (e *ParseError) Error() string {
	return fmt.Sprintf("parse error for %q: %s", e.Input, e.Msg)
}

// Function accepting io.Writer
func generateReport(w io.Writer, title string, items []string) {
	fmt.Fprintf(w, "\n=== %s ===\n", title)
	for i, item := range items {
		fmt.Fprintf(w, "  %d. %s\n", i+1, item)
	}
	fmt.Fprintf(w, "Total: %d items\n", len(items))
}

// Custom io.Reader
type UpperReader struct {
	r io.Reader
}

func NewUpperReader(s string) *UpperReader {
	return &UpperReader{r: strings.NewReader(strings.ToUpper(s))}
}

func (u *UpperReader) Read(p []byte) (int, error) {
	return u.r.Read(p)
}

func main() {
	// fmt.Stringer
	temps := []Temperature{{0}, {100}, {37}, {-40}}
	for _, t := range temps {
		fmt.Println(t)
	}

	// Custom error
	err := &ParseError{Input: "abc", Msg: "not a number"}
	fmt.Println("\nError:", err)

	// io.Writer — write to multiple targets
	var buf bytes.Buffer
	items := []string{"Go", "Rust", "Python", "TypeScript"}
	generateReport(&buf, "Top Languages", items)
	generateReport(nil, "", nil) // would need os.Stdout
	fmt.Print(buf.String())

	// Custom io.Reader
	reader := NewUpperReader("hello world from go")
	data, _ := io.ReadAll(reader)
	fmt.Println("\nUpperReader:", string(data))
}
